using Tern.App.Commands;
using Tern.App.Settings;

namespace Tern.App.Help;

public sealed record SettingFeature(string Property, string Name, string Category, string Description, string How)
{
    public string Id => "settings." + Property;
    public FeatureHelp Help => new(Id, Name, "Settings · " + Category, Description, "Available without a document. Settings affect Tern preferences, not the contents of saved documents.", "", CommandIds.Settings,
    ["Open Edit → Settings, or search Settings in the command palette. No document is required.", $"Choose {Category} in the category navigation, or type {Name} in Find a setting.", How, "Choose Done to apply and save your preferences. Reopen Settings to adjust the value again."]);
}

public static partial class FeatureCatalog
{
    public static IReadOnlyList<SettingFeature> SettingsFeatures { get; } =
    [
        new(nameof(AppSettings.Theme), "Theme", "Appearance", "Paper is light, Midnight is dark, and System follows the Windows appearance. Choose the contrast comfortable for you.", "Choose Paper, Midnight or System in Theme. The main application applies the appearance when Settings closes."),
        new(nameof(AppSettings.EditorFontFamily), "Editor font", "Appearance", "The source editor uses this font family. A comma-separated fallback list lets Windows choose an available typeface.", "Enter an installed font family such as Cascadia Code. Leave the field to accept it; a blank name is ignored."),
        new(nameof(AppSettings.EditorFontSize), "Editor font size", "Appearance", "Set the source text size from 8 to 48. Preview text has a separate size.", "Use the number field or its arrows to choose a source editor text size from 8 to 48."),
        new(nameof(AppSettings.PreviewFontSize), "Preview font size", "Appearance", "Set rendered document text size from 8 to 48 without changing the saved Markdown.", "Choose a preview text size from 8 to 48. Source text size remains independent."),
        new(nameof(AppSettings.PreviewFullWidth), "Use full preview width", "Appearance", "Use the available preview pane width instead of centering a narrow text column. Enabled by default. Turn it off to use the Reading width limit.", "Enable Use full preview width to fill the pane with readable content and small padding. Disable it if you prefer a centered column, then adjust Reading width."),
        new(nameof(AppSettings.ReadingWidth), "Reading width", "Appearance", "When Use full preview width is off, limit the centered text column from 360 to 1,600 device-independent units. This changes layout, not the Markdown or font size.", "Turn off Use full preview width, then choose a width from 360 to 1,600. Turn full width back on to use the whole pane again."),
        new(nameof(AppSettings.UiScale), "Interface text scale", "Appearance", "Scale application body text from 75% to 250%. Use 1 for 100%, 1.25 for 125%, or 1.5 for 150%. This is separate from Windows DPI scaling and the document editor/preview font sizes; headings keep their visual hierarchy.", "Choose a text scale from 0.75 to 2.5 and close Settings to apply it. Editor font size and Preview font size control document text separately; return this value to 1 for the default interface body text."),
        new(nameof(AppSettings.ReduceMotion), "Reduce motion", "Appearance", "Request reduced interface motion for a calmer experience. This does not change document content.", "Check Reduce motion to request fewer interface animations; uncheck it to use the standard behavior."),
        new(nameof(AppSettings.WordWrap), "Wrap long lines", "Editor", "Display long source lines across multiple visual lines. Wrapping never inserts line breaks into your file.", "Check Wrap long lines to avoid horizontal scrolling. Uncheck it to keep each source line on one visual line."),
        new(nameof(AppSettings.ShowLineNumbers), "Show line numbers", "Editor", "Show source line numbers beside the text to help navigation and discussion.", "Check Show line numbers to display the source editor gutter; uncheck to hide its numbers."),
        new(nameof(AppSettings.HighlightCurrentLine), "Highlight current line", "Editor", "Use a subtle background to mark the source line containing the caret.", "Check Highlight current line, then return to the editor and move the caret to see the highlighted line."),
        new(nameof(AppSettings.TabSize), "Tab size", "Editor", "Choose an indentation width of 1 to 16 spaces. Existing tab characters are displayed at this width.", "Choose the number of spaces used for indentation. Insert spaces when pressing Tab controls whether new indentation uses spaces or tabs."),
        new(nameof(AppSettings.InsertSpacesForTab), "Insert spaces when pressing Tab", "Editor", "When enabled, Tab inserts spaces using Tab size. When disabled, it inserts a tab character.", "Choose spaces for consistent indentation across editors, or uncheck to insert literal tab characters. Existing text is not converted."),
        new(nameof(AppSettings.SyncScroll), "Synchronise scrolling in split view", "Editor", "Move source and preview together using source positions. Available in Split view; turn it off to scroll each pane independently.", "Check Synchronise scrolling in split view, choose Split, then scroll either pane. Uncheck for independent pane positions."),
        new(nameof(AppSettings.DefaultViewMode), "Default view", "Editor", "Choose Source, Split or Reading for newly opened documents. Current view controls can switch an individual document.", "Choose Source to edit Markdown, Split for source and preview, or Reading for the preview alone."),
        new(nameof(AppSettings.DefaultProfile), "Default profile (new files)", "Editor", "Choose the Markdown dialect used for new documents. CommonMark is conservative; GFM adds GitHub features; Extended enables additional supported syntax.", "Choose a Markdown profile for new files. This does not rewrite Markdown or convert existing files."),
        new(nameof(AppSettings.RestoreSession), "Restore tabs and folder on startup", "Files", "Reopen saved document paths and the workspace on the next startup. Unsaved-work recovery is a separate protection.", "Check to restore your saved-file tabs and folder at startup. Do not rely on the restore list as a backup of unsaved text."),
        new(nameof(AppSettings.AutoReloadCleanDocuments), "Reload unmodified files changed on disk", "Files", "Automatically reload external changes only when the open document has no unsaved edits. Conflicting edits still require a decision.", "Check to reload clean documents changed by another program. Leave it off when you prefer to review external changes yourself."),
        new(nameof(AppSettings.EnsureFinalNewlineOnSave), "Ensure a final newline when saving", "Files", "Add a line break at the end of a nonempty document when it is saved. Empty documents remain empty.", "Enable this only if your tools expect a final line break. The change is applied on a subsequent save."),
        new(nameof(AppSettings.TrimTrailingWhitespaceOnSave), "Trim trailing whitespace when saving", "Files", "Remove trailing spaces on save while preserving a deliberate pair used for a Markdown hard line break.", "Enable to tidy trailing whitespace on the next save. Review the resulting text if your document uses meaningful spacing."),
        new(nameof(AppSettings.AllowExternalLinkOpening), "Allow opening links in other applications (asks first)", "Files", "Permit a confirmation prompt before a link is opened in a browser or another application. Turning it off blocks external launches.", "Check to allow reviewed external links, or uncheck to prevent Tern from launching them. Opening a web link can use the network."),
        new(nameof(AppSettings.SidebarVisible), "Show Library sidebar", "Layout", "Keep the Library sidebar visible, or hide it to give the document more horizontal room. View → Sidebar offers the same choice while writing.", "Enable Show Library sidebar to keep folder and navigation controls visible. Disable it for a wider writing area; use View → Sidebar to bring it back."),
        new(nameof(AppSettings.SidebarWidth), "Library sidebar width", "Layout", "Set the Library's preferred width from 180 to 800 device-independent units. You can also drag its divider while writing.", "Choose a width from 180 to 800. Close Settings to apply it. Keep enough room for both the Library and your document panes."),
        new(nameof(AppSettings.WorkspaceExclusions), "Workspace exclusion patterns", "Workspace", "Exclude workspace paths using one gitignore-style pattern per line. Patterns change scanning, not files; they take effect the next time a workspace opens. A .ternignore file is an alternative local to one workspace.", "Enter one reviewed pattern per line, such as drafts/. Close Settings, then safely close and reopen the workspace to rescan with those rules. Remove a pattern to include the paths again."),
        new(nameof(AppSettings.KeyBindings), "Keyboard shortcut bindings", "Keyboard", "Configure command shortcuts in the dedicated category and recording editor. Current bindings, conflicts and defaults are shown there.", "Choose Edit keyboard shortcuts, select a command and Record keys. Assign applies the candidate; Clear recording cancels it. Close the editor and Settings to persist the bindings."),
    ];

    public static IReadOnlyList<FeatureHelp> Subfeatures { get; } =
    [
        .. SettingsFeatures.Select(s => s.Help),
        Detail("editor.drop", "Drop files and pictures", "Editor", "Drag Markdown files (.md, .markdown, .mdown) or text notes (.txt) to open them, a folder to browse its contents, or PNG, JPEG, GIF, WebP and BMP pictures into the writing pane to choose whether to link or copy them. Other file types are refused with guidance; they are not opened or linked automatically.", "Choose a writable note. A new note asks where to save before picture insertion continues. A file or folder must exist locally.", CommandIds.ViewSplit, "Choose Split and drag the local item into the writing pane. Markdown or .txt opens in a tab, a folder appears as a directory tree, and a picture beside the Markdown file links immediately when dropped, selected or pasted with Ctrl+V; a picture from a subfolder or another location asks Link original or Copy image. Link uses its original path; Copy asks for a folder and filename and links the copy. Text notes remain editable and use the Markdown preview. Read any status message; unsupported and missing items are reported."),
        Detail("editor.practice", "Practice note and source-to-preview example", "Editor", "Try headings, bold text, a checklist, a quotation and a table in a small practice note. Source contains the writing marks; Reading preview shows their appearance.", "No account, connection or workspace is needed.", CommandIds.NewFile, "Choose Start here → Practise safely with a small note. Copy its example into a new document, choose Split and compare the writing with the preview. Try Undo, then Save as practice-note.md."),
        Panel("inspector.outline", "Document outline", "List document headings in order and navigate to a section by selecting its heading.", "Open a Markdown document containing # headings.", "Choose the inspector's Outline section. Select a heading to move to that section in the document."),
        Panel("inspector.links", "Links in document", "Inspect local and external links found in the active document. External links require permission before another application is opened.", "Open a document containing Markdown links.", "Open Links in the inspector. Review the target before selecting a link, and confirm only destinations you trust."),
        Panel("inspector.info", "Document information", "See word count, estimated reading time and saved-document information. Statistics describe the current document text.", "Open or create a document.", "Choose Details in the inspector and review Document info. Write or edit text and allow analysis to refresh the counts."),
        Panel("inspector.tags", "Document tags", "Inspect tags extracted from supported document metadata. An empty list means no supported tags were found.", "Open a document with supported tag metadata.", "Choose Details in the inspector and review Tags. In Source, front matter such as tags: [writing, notes] between --- lines can supply tags. Review the refreshed list after editing."),
        Panel("inspector.history", "Inspector History section", "The History tab explains local saved-text versions and opens the comparison and restoration window. It is separate from recent-file history.", "Open a saved document. Recorded versions begin with saves made by Tern.", "Choose History in the inspector, then Open version history. Select a version to compare it or open it as a separate unsaved copy."),
        Panel("inspector.brokenLinks", "Broken links and repair", "Find unresolved local links and choose an existing workspace target for an undoable repair. Save explicitly to write the repair.", "Open a workspace document with a broken local link.", "Choose Links in the inspector. Select the broken link, choose Repair selected link and the intended workspace target. Review the repair; Undo reverses it before saving."),
        new("library.recent", "Recent documents", "Library", "Recent history records file and URL references, not copies of document contents. Selecting a URL reuses its complete cached Markdown and assets when available; incomplete copies can retry downloads. Starting Tern does not automatically contact stored URLs. Remove a reference individually or clear recent history without deleting files.", "Available without a workspace. Open a saved document to populate recent history.", "", CommandIds.LibraryRecent, ["Choose Recent in the Library, or search Show Recent in the command palette.", "Select a file reference to open its file, or select a URL to reopen its cached editable unsaved copy or download it when needed. Use the row's remove action to forget one reference, or Clear recent history to forget all references.", "Open tabs and explicit workspace files remain independent. No physical document is deleted."]),
        Detail("library.files", "All Files", "Library", "Browse stacked physical folder and saved workspace trees. Expand descendants, use path tooltips, and select a root to target commands. Outside documents remain separate. Clearing recent history does not empty open roots.", "Open Folder browses an ordinary directory. Open Workspace restores a named persistent context. Neither is required to open individual files.", CommandIds.LibraryFiles, "Choose All Files. The tree shows supported Markdown/text notes and unexcluded folders, including empty folders; arbitrary binary files are not listed as notes. Use + Add to choose the selected root or outside all workspaces. Right-click a row for Create File, Create Folder or Create Workspace targeted to that row."),
        Detail("library.search", "Search results", "Library", "Revisit results from the latest workspace text search. This differs from filename Quick Open and from finding text inside one document.", "Open a workspace and run Search in Workspace. The panel is empty when there is no active search.", CommandIds.LibrarySearch, "Run Search in Workspace and enter a query. Choose Search in the Library to revisit its results, then select a result to open the file at the matching line."),
        Detail("library.backlinks", "Backlinks", "Library", "Find workspace documents that link to the active saved document. Backlinks describe incoming relationships, while the inspector Links tab describes links inside the active document.", "Open a workspace and a saved document within it.", CommandIds.LibraryBacklinks, "Choose Backlinks in the Library. Select a referring result to open the source document at its link. No results means the current workspace graph found no incoming links."),
        Detail("library.brokenLinks", "Broken Links", "Library", "List unresolved links across the workspace. The count badge signals issues to inspect; repairing a link requires reviewing its intended target.", "Open a workspace containing local links.", CommandIds.LibraryBrokenLinks, "Choose Broken Links in the Library and select a result to open its source. Inspect the target, then use the inspector Links tab for supported repair or edit the source manually."),
        Detail("library.tasks", "Tasks", "Library", "List unfinished Markdown task items found in workspace documents. The badge counts unfinished tasks; checking or unchecking a task changes document text only through an explicit edit.", "Open a workspace containing task-list markup such as - [ ] Write notes.", CommandIds.LibraryTasks, "Choose Tasks in the Library and wait for its scan. Select a task to open the source at that line. Use Toggle Task at Cursor to change completion, then save explicitly."),
        new("editor.lineEndings", "LF / CRLF / CR line endings", "Document format", "LF, CRLF and CR are line-break conventions. Existing files keep their text when opened; new notes default to Windows CRLF. Save, Save As and Save All preserve the selected LF, CRLF or CR convention. Encoding is separate.", "Open a writable document.", "", CommandIds.ChangeLineEnding, ["Open a writable document and click LF, CRLF or CR in the status bar.", "Choose LF (Unix / macOS), CRLF (Windows) or CR (classic Mac) to convert the open buffer.", "Review the buffer, then Save. All save actions preserve your selected line endings; character encoding remains separate."]),
        new("editor.encoding", "Encoding and BOM", "Document format", "Encoding determines how characters become bytes. BOM is an optional encoding marker. Preserve the detected format unless another tool requires a change.", "Open a document. Save or discard edits before reopening it with another decoding.", "", CommandIds.ChangeEncoding, ["Click the encoding label in the status bar or search Change Save Encoding.", "Choose the encoding required by the receiving tool. A conversion that would lose characters is refused.", "Save to write the selected encoding. Reopen with Encoding reads existing bytes differently; it is not the same operation."]),
        new("editor.scrollbars", "Pane boundaries and scrollbars", "Editor", "Drag the visible scrollbar thumb to move within a pane. Source and preview have independent bars; synchronized scrolling can link their movement.", "Open a document long enough to scroll.", "", CommandIds.ViewSplit, ["Choose Split so source and preview panes are visible.", "Drag either pane's scrollbar thumb or use the mouse wheel. The separator identifies the pane boundary.", "Use Settings → Editor → Synchronise scrolling to link the panes, or turn it off for independent scrolling."]),
        Detail("search.case", "Match case", "Find and replace", "Require capital and lowercase letters to match exactly. With this on, Cat differs from cat.", "Open a document and its Find bar.", CommandIds.Find, "Enter the search text, enable Match case, and move through matches. Turn it off for a case-insensitive search."),
        Detail("search.word", "Whole word", "Find and replace", "Match complete words rather than text inside a longer word. Searching cat can exclude concatenate.", "Open a document and its Find bar.", CommandIds.Find, "Enter a word and enable Whole word. Review the highlighted matches before replacing any text."),
        Detail("search.regex", "Regular expression search", "Find and replace", "Use a regex pattern to describe matches instead of literal text. Invalid patterns report an error instead of replacing text.", "Open a document and its Find bar. Use literal search if you are unfamiliar with regular expressions.", CommandIds.Find, "Enable the regex option and enter a pattern. Inspect every match before replacing; turn regex off to search punctuation literally."),
        Detail("search.replaceAll", "Replace all matches", "Find and replace", "Replace every match in the current document using the active case, whole-word and regex options. This edits the buffer; save explicitly.", "Open a writable document and the Replace bar.", CommandIds.Replace, "Enter search and replacement text, review the match count and options, then choose Replace all. Undo reverses the edit; Save writes it to disk."),
        Detail("search.navigation", "Previous and next search match", "Find and replace", "Move between matches without changing text. Search navigation wraps through the document.", "Open Find and enter text that has matches.", CommandIds.Find, "Use the up arrow for Previous match and the down arrow for Next match. The match status reports the current result."),
        Detail("search.replaceOne", "Replace this match", "Find and replace", "Replace the selected search occurrence, leaving other matches for review. The active search options still apply.", "Open Replace in a writable document and find a match.", CommandIds.Replace, "Enter the replacement text, review the selected occurrence, then choose Replace. Move to the next result when ready; save explicitly."),
        Detail("editor.panes", "Resize writing panes", "Editor", "Drag pane separators to give the Library, source, preview or inspector more space. Source and preview remain separate areas in Split view.", "Open a document and show the panes you want to resize.", CommandIds.ViewSplit, "Move the pointer onto a pane separator and drag it. Keep enough width to read the source, preview and inspector comfortably."),
        Detail("editor.fencedCode", "Fenced code blocks", "Markdown", "Surround multiline code with triple backticks. A language name after the opening fence requests syntax highlighting when supported.", "Open a writable document in Source or Split.", CommandIds.ViewSplit, "On separate lines enter an opening triple-backtick fence, your code, and a closing triple-backtick fence. Add a language such as csharp after the opening fence, then review the preview."),
        Detail("recovery.review", "Review recovered work", "Recovery", "After an interrupted session, Tern can offer checkpoint text beside the current disk file. Recovery is separate from the session restore list.", "A recoverable checkpoint must already exist. Do not interrupt a working session just to try this feature.", CommandIds.Help, "If Review recovered work appears at startup, compare Current disk file with Recovered local edits. Choose Ask later if you need more time."),
        Detail("recovery.restore", "Restore recovered text as a copy", "Recovery", "Restore as unsaved copy opens checkpoint text separately, preserving the current disk document. Save recovered copy writes to a chosen separate destination.", "The recovery review dialog is open for an existing checkpoint.", CommandIds.Help, "Review the checkpoint, then choose Restore as unsaved copy or Save recovered copy. Inspect the result before saving. Discard checkpoint removes that recovery reference; Ask later postpones the decision."),
        Detail("conflict.merge", "Merge external changes", "File conflicts", "Compare the original base, your open edits and current disk edits before accepting a combined result. A merge is reviewed text, not an automatic overwrite.", "The same saved file changed externally while it had unsaved edits in Tern.", CommandIds.ReloadFromDisk, "When a conflict is reported, choose merge and select a conflicting region. Review the three text versions and the editable merged result before Accept merged text."),
        Detail("conflict.choices", "Keep mine, Take disk, Both and Original", "File conflicts", "For a selected merge region, Keep mine uses your text, Take disk uses the external text, Both includes both versions, and Original uses their common base.", "Open a merge review containing conflicting regions.", CommandIds.ReloadFromDisk, "Select a conflict, choose the desired region result, and review the full merged text. Cancel leaves the merge unaccepted. Save explicitly only when the reviewed result is correct."),
        Detail("history.compare", "Compare saved versions", "History", "Review the text of a recorded local version against the current document. History is local saved-text history, not an independent backup.", "Open a saved document with recorded versions.", CommandIds.ShowHistory, "Open Document Version History, select a version and compare its text before deciding whether to restore it."),
        Detail("history.restore", "Restore a version as an unsaved copy", "History", "Open a historical version in a separate unsaved document. The current document and its saved file are preserved.", "Open a saved document with recorded versions.", CommandIds.ShowHistory, "Select a version, review it and choose Open as unsaved copy. Save the new copy to a separate path if you want to keep it."),
        Detail("library.missing", "Missing or inaccessible file", "Library", "A missing or inaccessible reference is marked so it can be distinguished from an available file. Removing the reference does not delete a physical file.", "A recent or workspace file reference is unavailable.", CommandIds.QuickOpen, "Check the displayed path and restore access or locate the file. Retry opening it, or remove the stale recent reference if it is no longer useful."),
        Detail("workspace.exclusions", "Workspace exclusions and .ternignore", "Workspace", "Exclude workspace paths using Settings → Workspace → Workspace exclusion patterns, or a .ternignore file local to a workspace root. Both use gitignore-style patterns and do not delete documents.", "Review existing patterns before changing global settings or a workspace's .ternignore file.", CommandIds.Settings, "Add one reviewed pattern per line, such as drafts/, in Workspace exclusion patterns or .ternignore. Save the configuration, then safely close and reopen the affected workspace to apply the scan rules. Remove the pattern later to include those files again."),
        Detail("workspace.purpose", "Why use a workspace?", "Workspace", "A workspace groups an ordinary project folder for its explorer, search, links and tasks. It is optional: a single Markdown document can be opened, created and saved without any workspace.", "No workspace or open document is required to learn the difference.", CommandIds.OpenFolder, "Choose Open Folder when you already have a project folder. Choose Create Workspace for a new empty folder. Use standalone New document or Open Files for notes that do not need project-wide navigation."),
        Detail("workspace.standalone", "Open, create and save without a workspace", "Workspace", "Standalone documents remain ordinary files. They support Markdown editing, preview, Save and Save As without attaching their folders as projects.", "No workspace is required.", CommandIds.NewFile, "Choose New document or Open Files, write your text and Save to a filename and location. You may attach a workspace later for its explorer and project search; the file does not need conversion."),
        Detail("workspace.multiple", "Multiple workspaces", "Workspace", "Keep multiple project roots open and switch the active explorer/search/link graph between them. Document tabs and unsaved buffers remain open while you switch.", "Open at least one project folder; adding another existing folder creates another open root, not a duplicate of the same root.", CommandIds.OpenFolder, "Open another folder, then choose the desired root in the Library workspace selector. Browse that root's files. Close Workspace detaches one root; Close All Workspaces reviews all affected documents before detaching the roots."),
        Detail("workspace.switch", "Switch the active workspace", "Workspace", "The active root determines the Library tree and workspace search/link results. Switching does not close documents or discard unsaved edits. For nested roots, the nearest matching root owns a document.", "Open two or more workspace roots.", CommandIds.LibraryFiles, "Choose the workspace you want in the Library selector. Its explorer shows files belonging to that root, while the document tabs keep the files you opened from all roots."),
        Detail("workspace.newRoot", "Create a workspace folder", "Workspace", "Create a new empty project folder without overwriting an existing folder. A workspace remains an ordinary folder of files.", "Choose a parent location where you can create a new folder and enter an unused folder name.", CommandIds.CreateWorkspace, "Choose Create Workspace, select the parent location and enter the new folder name. After it opens, create a Markdown file there or use New document and Save into that folder. Use Open Folder for an existing project."),
        Detail("workspace.closeAllHelp", "Close all workspaces safely", "Workspace", "Detach all open project roots after reviewing unsaved changes across the affected groups. Standalone and unnamed documents remain separate; physical folders and files are preserved.", "At least one workspace is open. Save, Discard and Cancel decisions are completed before roots are detached.", CommandIds.CloseAllWorkspaces, "Choose Close All Workspaces and review each unsaved-document decision. Cancel keeps the close operation from completing; Save preserves the edits, while Discard abandons those edits. Reopen folders when you need their project navigation again."),
        Detail("file.renameLinks", "Review relative-link updates after rename", "File", "A saved-file rename can propose relative-link repairs. The file is already renamed when review appears. Open documents receive undoable edits that require Save; closed files are written only when their reviewed contents still match.", "Rename a saved document with affected supported relative links in its workspace. Naming an unsaved draft does not rename a physical file.", CommandIds.Rename, "In Review links after rename, inspect every file and its Before/After text. Choose Apply reviewed link updates only when correct, or Keep links unchanged to preserve the rename without repairing links. Review any conflict report; save modified open documents explicitly."),
        Detail("export.text", "Plain text export", "Export", "Export readable text without Markdown formatting to a separate .txt file. The source document is preserved.", "Open a document.", CommandIds.ExportHtml, "Open Export, choose Plain text in Format, browse to a separate output file and choose Export. Review the generated text."),
        Detail("reset.history", "Reset recent history", "Reset", "Clear stored recent and pinned references. Open document tabs, workspace contents and physical files are independent.", "No document is required.", CommandIds.Reset, "Open Reset Tern, select Recent history and review the other selected categories before choosing Reset selected application data."),
        Detail("reset.preferences", "Reset preferences and keyboard shortcuts", "Reset", "Restore default preferences and command bindings. This changes the application configuration rather than document contents.", "No document is required. Note any custom shortcuts you want to recreate.", CommandIds.Reset, "Open Reset Tern, select Preferences and keyboard shortcuts, review the scope, then reset the selected categories."),
        Detail("reset.session", "Reset session restore list", "Reset", "Clear the list used to reopen saved tabs and the workspace on startup. Open drafts and recovery copies are preserved.", "No document is required.", CommandIds.Reset, "Open Reset Tern and select Session restore list. Review the scope before resetting selected application data."),
        Detail("reset.remoteCache", "Clear cached online documents and assets", "Reset", "Remove managed online Markdown snapshots and downloaded dependencies from the remote cache. User downloads, attachments, drafts, recovery copies and AI credentials remain separate.", "Close cached online tabs first. Save a portable local copy when you want to keep one.", CommandIds.Reset, "Open Reset Tern, select Cached online documents and assets, review the scope and choose Reset selected. Reopening an uncached URL needs a connection again."),
        Detail("reset.index", "Reset search indexes", "Reset", "Remove rebuildable workspace search-index data. This does not remove source files or folders.", "Close the workspace first.", CommandIds.Reset, "Close the workspace, open Reset Tern and select Search indexes. Reopen the workspace afterward so its index can be rebuilt."),
        new("ai.workflow", "Work with or without AI", "AI Connections", "AI can draft, rewrite and explain Markdown. Save connections once in Settings, switch services in the main toolbar, then use Write with AI to update the active note in one undoable edit. The guide answers general questions without attaching your note. Editing and export still work offline. AI can be wrong and cloud services may charge.", "Cloud APIs need API access; local Ollama needs a running server and model. GitHub Copilot uses its saved CLI connection. MCP supplies tools rather than a writing model. Opening a window or selecting a connection sends nothing.", "", CommandIds.AIConnections,
            ["Choose Edit → Settings → AI connections, then Manage AI connections. Choose a service, Configure connection, enter a name, model and key, then Continue to validation. Validate connection sends a fixed test message; Save connection stores the settings securely.",
             "All saved API, GitHub Copilot and MCP connections appear in the main toolbar. Select an API or Copilot connection for Write with AI; select an MCP connection for Open MCP tools. Share the active note and your question only when you deliberately choose Generate & update note.",
             "Press Alt+Space in Source, Reading preview or the Reference pane. In the larger writing panel, choose a connection first, review its destination, describe a change and inspect Review the exact request before Generate & update note. The target is the active main tab, even when the Reference pane has focus.",
             "Check the update in Split. Undo restores the previous draft; File → Save writes it to disk. Ask general questions in the feature guide; guide answers do not modify notes."]),
        Detail("ai.openaiCompatible", "OpenAI-compatible AI connection", "AI Connections", "Use a compatible non-streaming text chat-completions endpoint. Provider-specific tools, image inputs and authentication variants are outside this adapter.", "Obtain an HTTPS cloud endpoint or run a compatible local server. You need its model name and any required API key.", CommandIds.AIConnections, "Choose the OpenAI-compatible protocol, enter the full chat-completions endpoint and model, then Continue to validation. Validate connection sends a fixed test message; read the result and Save connection. Use Try your own message (optional) for a separate reviewed question."),
        Detail("ai.guidedSetup", "Guided AI connection setup", "AI Connections", "Follow three stages: Choose service, Configure connection, and Validate and save. Back keeps entered values. Opening setup, navigating and saving make no network request; Validate connection deliberately contacts the selected model.", "Have access to the selected service API or a running local model server. Website subscriptions do not necessarily include API access.", CommandIds.AIConnections, "Use the AI service menu for OpenAI API, Anthropic API (Claude), Ollama (local), Other compatible API, GitHub Copilot or MCP server. The selection enables the appropriate fields and setup. Create connection starts a new profile. Selecting any saved connection stays on Choose service and updates the AI service menu; choose Configure connection to open its settings, or Delete connection to remove it after confirmation. Setup guide opens official documentation for the selected service, including GitHub Copilot authentication and the MCP 2025-11-25 Streamable HTTP specification. For an API, enter a connection name, exact model ID and required key; use Advanced only for custom addresses. Choose Continue to validation, review the destination, and choose Validate connection to send the fixed test message. Read success or the error, then Save connection. Saving an untested connection is allowed but does not establish that it works. Expand Try your own message (optional) only when you want to review and send your own text."),
        Detail("ai.accountAccess", "ChatGPT accounts and API access", "AI Connections", "An OpenAI API connection is separate from signing in to ChatGPT on the web. Tern does not import ChatGPT conversations, subscriptions or browser credentials. The service's API account controls model access and charges.", "Obtain API access, credentials and a model identifier from the service you intend to use.", CommandIds.AIConnections, "Select OpenAI API or Other compatible API. Enter the complete API endpoint and a model available to that API account. Start with a small non-sensitive reviewed message; do not paste website passwords or session cookies."),
        Detail("ai.claude", "Claude native Anthropic API", "AI Connections", "Use Claude through Anthropic's native Messages API. A Claude consumer subscription does not supply API credentials. This adapter sends one reviewed text message without tools or automatic document access.", "Obtain an Anthropic API key and a Claude model identifier available to that API account.", CommandIds.AIConnections, "Choose Anthropic API (Claude) in the service presets. Confirm the preset Messages API endpoint, enter the available model ID and API key, then Continue to validation. Validate connection sends a fixed test message; read its result and Save connection. Use Try your own message (optional) for a separate reviewed question."),
        new("ai.mcp", "MCP server connections and tools", "AI Connections", "Save a manual tool-server connection, validate it by discovering tools, and review each tool call separately. Supported: MCP 2025-11-25 Streamable HTTP with JSON or request-scoped SSE. MCP does not provide an AI model; OAuth and stdio are unsupported.", "Obtain a compatible HTTP MCP endpoint and any required bearer token from its administrator. Newer protocol revisions need compatible mode.", "", CommandIds.AIConnections,
        ["Open AI Connections and choose MCP server in the AI service menu, then Configure connection. Selecting a saved server stays on Choose service until Configure connection is clicked. Setup guide opens the official MCP 2025-11-25 Streamable HTTP specification. Opening or loading saved settings sends nothing and attaches no document or filesystem roots.", "In Configure, select a saved connection or enter its name, full HTTPS endpoint (HTTP allowed on loopback) and optional bearer token. Ask the administrator for MCP 2025-11-25 compatibility; OAuth login and stdio processes are not supported.", "Continue to Validate and save. Connect and discover tools initializes the server and lists tools; it does not run one. Read any endpoint, authentication or compatibility error before trying again. Save connection stores the settings and protects the token in Windows Credential Manager.", "Select the saved MCP connection in the main toolbar and choose Open MCP tools. The saved server is selected without a request. Choose Connect and discover tools; in Review tools, select a discovered tool and read its description and input schema as untrusted information. Enter the exact JSON object arguments you authorize. A tool may change server files or accounts, send messages or incur costs.", "Review the server, tool and arguments before checking consent and choosing Run reviewed tool. Cancel stops waiting but cannot undo effects already performed. Results are untrusted JSON, not document edits; calls are never automatically retried. Reopen saved settings later, or use Manage saved connections to delete them."]),
        new("ai.copilot", "Configure and write with GitHub Copilot", "AI Connections", "Save a Copilot CLI connection and use it from the main toolbar to write or answer guide questions. The writing panel sends the active note only after Generate; the separate question tool sends only reviewed text. Ordinary writing works without Copilot.", "You need GitHub Copilot access, installed native copilot.exe, and a personal-account-owned fine-grained GitHub token with the Copilot Requests account permission. A website password, classic token or OpenAI key is not a substitute.", "", CommandIds.AIConnections,
        ["Choose Edit → Settings → AI connections → Manage AI connections, then select GitHub Copilot in the AI service menu and Configure connection. Selecting a saved Copilot connection stays on Choose service until Configure connection is clicked. Setup guide opens GitHub's official CLI authentication instructions. Opening or loading saved settings sends nothing.", "In Configure, select a saved connection or enter a connection name and your fine-grained GitHub token owned by your personal account with the Copilot Requests account permission. Copilot Chat permission is not required. Keep Model set to auto for a first test; use Advanced to check the trusted native copilot.exe location.", "Continue to Validate and save. Validate connection sends the fixed test message through the selected CLI and model, without attaching a document. Provider usage may apply. Read success or the error; check token permission, Copilot entitlement, model and CLI path when validation fails.", "Choose Save connection to keep metadata and store the token in Windows Credential Manager. The saved connection appears in the main toolbar and in the shared saved-connections list. Select it to modify settings or choose Delete connection after review. Manage saved connections also provides New connection and Delete saved connection.", "Choose the saved Copilot connection in the main toolbar and Write with AI to edit the active note. Review the exact request before Generate & update note; validation sends a fixed test first, then the note and instruction. Undo restores the draft. Copilot requests are limited to 8,192 characters including the note and instruction; @mentions and CLI commands are not accepted. For a separate question in Try connection, review the text, check consent, then Send reviewed text; that answer is not applied automatically.", "Cancel request stops waiting but cannot recall text already received. Editing the CLI destination clears a restored token so you can review and enter it again. Live account and model availability remain user-specific and unverified by this guide."],
        AdvancedDetails: "The adapter runs native copilot.exe with a reviewed flag set for version 1.0.95, isolated configuration and an empty working directory. It disables built-in tools, IDE context and automatic workspace attachments. Explicitly saved tokens use Windows Credential Manager; unsaved tokens stay in memory. The token is passed through the child process environment rather than arguments or metadata JSON. This is not an operating-system sandbox. New CLI versions and live provider/account compatibility require separate validation."),
        Detail("ai.ollama", "Native Ollama AI connection", "AI Connections", "Use the Ollama text-chat protocol for a running local model server. This is a separate adapter from the OpenAI-compatible endpoint.", "Start Ollama and make the requested model available on that server.", CommandIds.AIConnections, "Choose native Ollama, enter its chat endpoint and model, then Continue to validation. Validate connection sends a fixed test message; read the result and Save connection. Use Try your own message (optional) for separately reviewed text."),
        Detail("ai.profiles", "Save and remove an AI connection", "AI Connections", "Keep named API, MCP and Copilot settings for reuse. Secret keys are stored separately in Windows Credential Manager rather than metadata JSON. Saving does not contact a provider.", "Configure a connection on Windows. Validation contacts the selected service only when requested.", CommandIds.AIConnections, "Enter a connection name during Configure and continue to Validate and save. Validate connection tests API generation with a fixed message; Save connection or Save changes stores settings without sending. Selecting any saved API, Copilot or MCP connection in the shared list stays on Choose service. Choose Configure connection to modify its settings, or Delete connection and confirm removal. Create connection starts a fresh setup using the AI service menu. All saved connections appear in the main toolbar; MCP uses Open MCP tools rather than note generation."),
        Detail("ai.review", "Review AI content and cancel requests", "AI Connections", "In Try your own message (optional), only the exact manually pasted message is sent after consent. Validate connection uses a separate fixed test message. Changing the endpoint, model, provider, key or message invalidates that review. Cancel cannot recall data already received by a service.", "Configure a compatible AI connection. Do not paste private text you do not want that service to receive.", CommandIds.AIConnections, "On Validate and save, expand Try your own message (optional). Read the endpoint and exact message, check consent, then Send request. Use Cancel request to stop waiting; review any response before copying it into a document."),
    ];

    private static FeatureHelp Panel(string id, string name, string description, string prerequisite, string action) =>
        new(id, name, "Inspector", description, prerequisite, "", CommandIds.ToggleRightPanel,
        ["Open the document inspector using View → Toggle Outline Panel or its current command-palette entry.", prerequisite, action, "Select a different inspector section or close the panel when finished. Viewing information does not save or modify the document."]);

    private static FeatureHelp Detail(string id, string name, string category, string description, string prerequisite, string command, string action) =>
        new(id, name, category, description, prerequisite, "", command,
        [$"Before you start: {prerequisite} This guide never performs the action automatically.", action, "Review the result and any confirmation before saving or replacing data. You can skip, replay or exit this lesson at any time."]);
}
